arguments.command:
cd /tmp/vally-eval-trial-8beY0f && mkdir -p tests/CheckoutPricing.UnitTests/Acceptance && cat > src/CheckoutPricing.Application/Checkout.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier { Standard, Gold }

public sealed class Checkout
{
    public decimal CalculatePayableTotal(CustomerTier tier, decimal subtotal) => subtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/Acceptance/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Acceptance;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_receives_the_approved_discount()
    {
        var total = new Checkout().CalculatePayableTotal(CustomerTier.Gold, 100.00m);

        Assert.Equal(95.00m, total);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | tail -20

